function simulateNav(fixType) {
  let state = {
    currentView: "home",
    previousView: null,
    detailsOriginView: null
  };

  function switchView(viewName) {
    state.previousView = state.currentView;
    state.currentView = viewName;
  }

  function openDetails(item) {
    state.detailsOriginView = state.currentView;
    switchView("details");
  }

  function exitPlayer() {
    let returnView = state.previousView || "home";
    if (returnView === "player") returnView = "home";
    switchView(returnView);
  }

  function handleBackNavigation() {
    if (state.currentView === "player") {
      exitPlayer();
    } else if (state.currentView === "details") {
      let returnView;
      if (fixType === "current_worker_fix") {
        returnView = state.previousView || "home";
        if (returnView === "details") returnView = "home";
      } else if (fixType === "guard_player_and_details") {
        returnView = state.previousView || "home";
        if (returnView === "details" || returnView === "player") returnView = "home";
      } else if (fixType === "origin_aware") {
        returnView = state.detailsOriginView || state.previousView || "home";
        if (returnView === "details" || returnView === "player") returnView = "home";
      }
      switchView(returnView);
    } else if (state.currentView !== "home") {
      switchView("home");
    } else {
      console.log("Exit app threshold");
    }
  }

  // Journey: movies -> details -> player -> exitPlayer -> details -> Back
  switchView("movies");
  openDetails({ title: "Dune" });
  switchView("player");
  handleBackNavigation(); // exit player
  handleBackNavigation(); // exit details
  return state.currentView;
}

console.log("Current worker fix result:", simulateNav("current_worker_fix"));
console.log("Guard player & details result:", simulateNav("guard_player_and_details"));
console.log("Origin aware result:", simulateNav("origin_aware"));
'

