// Test 28: Hierarchical Back navigation loop prevention in details view
await runAdversarialTest('NAV', 'Hierarchical Back navigation: details -> details must not lock user in infinite loop', async () => {
  const { app } = createTestDom('http://localhost/#home');
  app.init();

  // User opens details for Item 1
  app.openDetails({ title: 'Item 1', year: '2024', rating: '8.0' });
  assert(app.state.currentView === 'details');
  assert(app.state.previousView === 'home');

  // While in details, user opens details for related Item 2
  app.openDetails({ title: 'Item 2', year: '2024', rating: '8.5' });
  assert(app.state.currentView === 'details');
  // State now has previousView === 'details'

  // Press Back key
  app.handleBackNavigation();

  // DEFECT CHECK: Did Back key trap user in 'details'?
  if (app.state.currentView === 'details') {
    throw new Error(`INFINITE LOOP TRAP DETECTED: Back key pressed on details resulted in currentView='details'! User cannot escape details view with TV remote back key!`);
  }
  assert(app.state.currentView === 'home', `Expected Back key to return to 'home', got ${app.state.currentView}`);
});

